//! AllBlack11's identity in words and links: the product line, the creator credit and the one
//! URL the credit opens. Pure, so the rules (an exact HTTPS address, no tracking parameters, an
//! accessible name that says what the link is) are tested.
//!
//! Colors and the icon are not here: colors are `uitheme` tokens (`Palette::brand`) and the icon
//! is generated by `assets/brand/brand_icon.py` and compiled in as resources.
//! The creator credit is separate from the license and third-party notices, which are untouched.

/// The product name, spelled the same everywhere.
pub const NAME: &str = "AllBlack11";

/// One line under the name on Home. Short and plain, no jargon.
pub const TAGLINE: &str = "Pick a window, see what can change, preview it, keep it or undo it.";

/// What About says about how far this build has been checked. It is a statement of fact for the
/// build it ships in. Change it only when the facts change: it says what has been run, and the
/// full hardware pass in `docs/dev/SMOKE-TEST.md` is not finished.
pub const VERIFICATION_STATUS: &str = "Pre-release. Unit-tested and built for ARM64 and x64. The ARM64 build has been run on a Windows 11 ARM64 PC by its author; the full hardware test pass is not finished.";

/// The creator credit, as it reads on Home and in About. The plain text is complete without any
/// symbol, link or heart glyph.
pub const CREDIT_PREFIX: &str = "Made with love by ";
pub const CREATOR: &str = "TH0MSX";
pub const CREDIT_URL: &str = "https://github.com/TH0MSX";

/// What a screen reader announces for the link. The visible text stays "TH0MSX".
pub const CREDIT_LINK_NAME: &str = "TH0MSX - creator's GitHub profile";

/// The whole sentence, for plain-text uses (the About text, a copied report).
pub fn credit_text() -> String {
    format!("{CREDIT_PREFIX}{CREATOR}")
}

/// A link is opened only if it is an `https://github.com/` address with no query, fragment,
/// credentials or whitespace, so a typo or a later edit cannot turn the credit into something
/// else, and no tracking parameter can be added.
pub fn is_safe_profile_url(url: &str) -> bool {
    let Some(rest) = url.strip_prefix("https://github.com/") else {
        return false;
    };
    !rest.is_empty()
        && rest
            .chars()
            .all(|c| c.is_ascii_alphanumeric() || c == '-' || c == '_' || c == '/')
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_credit_reads_exactly_as_specified() {
        assert_eq!(credit_text(), "Made with love by TH0MSX");
        assert_eq!(CREATOR, "TH0MSX");
    }

    #[test]
    fn the_credit_link_is_the_verified_profile_and_nothing_more() {
        assert_eq!(CREDIT_URL, "https://github.com/TH0MSX");
        assert!(is_safe_profile_url(CREDIT_URL));
        assert!(!CREDIT_URL.contains('?') && !CREDIT_URL.contains('#'));
    }

    #[test]
    fn only_plain_https_github_profile_links_pass() {
        for bad in [
            "http://github.com/TH0MSX",
            "https://github.com/TH0MSX?utm_source=app",
            "https://github.com/TH0MSX#readme",
            "https://github.com.evil.example/TH0MSX",
            "https://user@github.com/TH0MSX",
            "https://github.com/",
            "https://github.com/TH0 MSX",
            "javascript:alert(1)",
            "file:///C:/Windows/System32/calc.exe",
            "",
        ] {
            assert!(!is_safe_profile_url(bad), "{bad}");
        }
    }

    #[test]
    fn the_accessible_name_says_what_the_link_is() {
        assert!(CREDIT_LINK_NAME.starts_with(CREATOR));
        assert!(CREDIT_LINK_NAME.contains("GitHub profile"));
    }
}
